"""Provenance and licensing facts the dataset card is obliged to state.

A synthetic page is not a single work. Three upstream sources are composited
into it, each under its own terms, and one of them - the drafted letter body -
is machine output whose provenance a consumer cannot recover from the pixels:

* **The letter text** is generated by a hosted instruct model. The model id
  travels in every source record's ``generation`` block, so the card reports
  the ids actually observed in the corpus rather than a constant that could
  drift from what was run. :data:`TEXT_MODEL_FALLBACK` is only used when no
  record carried one.
* **The logos** come from the ``thesvg`` icon corpus, whose per-file source,
  author and licence are recorded in ``attribution.csv`` beside the images.
  That file is copied into the export tree verbatim, because a licence that
  only exists on the machine that built the dataset is not a licence the
  dataset carries.
* **The signatures** come from UTSig, a research corpus with a paper to cite
  and no commercial grant.

The stamps and letterheads are drawn by this pipeline from those logos, which
is the reason for :data:`NON_COMMERCIAL_NOTICE`: a rendered مهر carrying a real
company's mark looks like that company's seal, and the only defensible framing
is that these pages exist to test an OCR model and nothing else.

Nothing here is derived from the render tree, so the module has no dependency
on the writers and can be read on its own to answer "what may I do with this
dataset".
"""

from __future__ import annotations

import csv
import logging
import shutil
from collections import Counter
from dataclasses import dataclass
from pathlib import Path
from types import MappingProxyType
from typing import Any, Final, Mapping

from ...config import HuggingFaceConfig, SynthConfig
from ..common.io_utils import relative_to_repo

__all__ = [
    "LOGO_CORPUS",
    "LogoAttribution",
    "NON_COMMERCIAL_NOTICE",
    "SIGNATURE_CORPUS",
    "SYNTHETIC_NOTICE",
    "TEXT_MODEL_FALLBACK",
    "logo_attribution_target",
    "write_logo_attribution",
]

_LOGGER: Final[logging.Logger] = logging.getLogger("fa_ocr_lora.export.attribution")

#: Model credited for the letter bodies when no source record names one. The
#: live value is read per sample from ``generation.model``; this is the
#: pipeline's default, kept here so a corpus rendered from records that predate
#: that field is still attributed rather than silently unattributed.
TEXT_MODEL_FALLBACK: Final[str] = "nvidia/nemotron-3-nano-30b-a3b"

#: Filename of the logo licence manifest, both in ``paths.logos_dir`` where the
#: download script writes it and in the export tree where it is republished.
LOGO_ATTRIBUTION_FILENAME: Final[str] = "attribution.csv"

#: Where the logos came from and what the consumer must carry forward.
LOGO_CORPUS: Final[Mapping[str, str]] = MappingProxyType(
    {
        "name": "thesvg",
        "url": "https://github.com/glincker/thesvg",
        "attribution_file": f"attribution/{LOGO_ATTRIBUTION_FILENAME}",
        "terms": (
            "Per-file licences - CC0-1.0, MIT and Apache-2.0 - are recorded in "
            "the republished manifest, one row per icon, with its upstream URL "
            "and author. The MIT and Apache-2.0 rows require that notice to "
            "travel with any redistribution, which is why the manifest ships "
            "inside this dataset rather than being linked."
        ),
    }
)

#: Where the signatures came from, and the paper the dataset's authors ask for.
SIGNATURE_CORPUS: Final[Mapping[str, str]] = MappingProxyType(
    {
        "name": "UTSig",
        "url": "https://www.kaggle.com/datasets/adibhossen/utsig-persian-signature-dataset",
        "citation": (
            "Soleimani, A., Fouladi, K., & Araabi, B. N. (2017). UTSig: A "
            "Persian offline signature dataset. IET Biometrics, 6(1), 1-8. "
            "https://doi.org/10.1049/iet-bmt.2015.0058"
        ),
        "terms": (
            "A research corpus of real people's handwriting, released for "
            "academic use. The images are composited unmodified onto the "
            "generated pages, so anyone using this dataset inherits that "
            "restriction: research use, with the paper above cited, and no "
            "commercial use or biometric enrolment."
        ),
    }
)

#: The single most important sentence on the card.
SYNTHETIC_NOTICE: Final[str] = (
    "Every letter in this dataset is synthetic. The organisations, addresses, "
    "registration numbers, national ids, phone numbers, dates and signatory "
    "titles are generated - they name no real correspondence, no real person, "
    "and no real transaction. Nothing here should be read as a record of "
    "anything that happened."
)

#: Why the logos and stamps are allowed to look real.
NON_COMMERCIAL_NOTICE: Final[str] = (
    "The letterheads and مهر stamps are drawn by the pipeline from third-party "
    "brand marks, so a page can carry a real organisation's logo inside a "
    "seal that organisation never issued. They are there because an OCR model "
    "has to read pages that look like this, and for no other reason: research "
    "and evaluation use only, no commercial use, and no implication that any "
    "named organisation authored, endorsed or sealed any of these documents."
)


@dataclass(frozen=True, slots=True)
class LogoAttribution:
    """What the logo licence manifest contained, and where it was republished.

    Attributes:
        source: The manifest read, or ``None`` when it was absent.
        exported: Tree-relative path it was copied to, or ``None``.
        rows: Icons the manifest covers.
        licences: ``(licence, count)`` pairs, most common first, for the card's
            summary table.
    """

    source: Path | None = None
    exported: str | None = None
    rows: int = 0
    licences: tuple[tuple[str, int], ...] = ()

    @property
    def available(self) -> bool:
        """Whether a manifest was found and republished."""
        return self.exported is not None and self.rows > 0

    def as_dict(self) -> dict[str, Any]:
        """Return the record as JSON-serialisable state for ``dataset_info``.

        ``source`` is reported repo-relative. It is the path on the machine that
        built the corpus, and ``dataset_info.json`` is published: an absolute one
        would put the builder's home directory on a public dataset page, where it
        tells a consumer nothing they can use.
        """
        return {
            "source": (
                relative_to_repo(self.source) if self.source is not None else None
            ),
            "file_name": self.exported,
            "icons": self.rows,
            "licenses": {name: count for name, count in self.licences},
        }


def logo_attribution_target(settings: HuggingFaceConfig) -> Path:
    """Return the path the logo manifest is republished to.

    Args:
        settings: The ``huggingface`` config section.

    Returns:
        ``<output_dir>/attribution/attribution.csv``.
    """
    return settings.output_dir / "attribution" / LOGO_ATTRIBUTION_FILENAME


def _count_licences(path: Path) -> tuple[int, tuple[tuple[str, int], ...]]:
    """Count rows and licence ids in the logo manifest.

    Args:
        path: The manifest to read.

    Returns:
        The row count and ``(licence, count)`` pairs, most common first. A row
        with no licence recorded is counted under ``"unspecified"`` rather than
        dropped, so the totals always add up to the row count.
    """
    counter: Counter[str] = Counter()
    rows = 0
    with path.open(encoding="utf-8", newline="") as handle:
        for row in csv.DictReader(handle):
            rows += 1
            counter[(row.get("License") or "").strip() or "unspecified"] += 1
    ordered = tuple(
        sorted(counter.items(), key=lambda item: (-item[1], item[0]))
    )
    return rows, ordered


def write_logo_attribution(
    config: SynthConfig, settings: HuggingFaceConfig
) -> LogoAttribution:
    """Republish the logo licence manifest into the export tree.

    Copied rather than summarised: the MIT and Apache-2.0 rows carry a notice
    requirement, and a count of them is not a notice.

    Args:
        config: Loaded configuration, for ``paths.logos_dir``.
        settings: The ``huggingface`` config section.

    Returns:
        What was copied. A missing or unreadable manifest is logged and returns
        an empty record - the export still completes, and the card says the
        manifest was unavailable instead of claiming licences it cannot show.
    """
    source = config.paths.logos_dir / LOGO_ATTRIBUTION_FILENAME
    if not source.is_file():
        _LOGGER.warning(
            "no logo attribution manifest at %s; the dataset card will say so "
            "rather than list licences it cannot show",
            source,
        )
        return LogoAttribution(source=None)
    target = logo_attribution_target(settings)
    try:
        rows, licences = _count_licences(source)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
    except (OSError, UnicodeDecodeError, csv.Error) as error:
        _LOGGER.warning(
            "logo attribution manifest %s could not be republished: %s", source, error
        )
        return LogoAttribution(source=source)
    _LOGGER.info(
        "republished %d logo attribution row(s) to %s", rows, target
    )
    return LogoAttribution(
        source=source,
        exported=f"attribution/{LOGO_ATTRIBUTION_FILENAME}",
        rows=rows,
        licences=licences,
    )
